INSERT INTO role_permissions (id, role_id, permission_id) SELECT gen_random_uuid()::text, r.id, p.id FROM roles r JOIN permissions p ON p.key IN ('analytics.read','campaigns.archive','campaigns.create','campaigns.publish','campaigns.read','campaigns.update','industries.manage','industries.read','navigation_menus.create','navigation_menus.delete','navigation_menus.publish','navigation_menus.read','navigation_menus.update','product_categories.manage','product_categories.read') WHERE r.key='ADMIN' AND NOT EXISTS (SELECT 1 FROM role_permissions x WHERE x.role_id=r.id AND x.permission_id=p.id);
